{"m":450,"c":"KS.06","l":"oz-ozini-rivojlantirish-va-kasbiy-osish","k":"qollash","d":2,"s":"Pedagog zid ma’lumotlar asosida noaniq vazifani bajarib, kutilmagan vaziyat uchun ham harakat rejasini tuzdi. Bu nimani ko‘rsatadi?","o":["Kasbiy kompetentlikning amalda namoyon bo‘lishini","Faqat nazariy bilimning yodlanganini","Lavozim vakolatining kengligini","Ish stajining uzoq davom etganini"],"a":0,"e":"Kasbiy kompetentlik murakkab, noaniq va kutilmagan vaziyatlarda bilim hamda ko‘nikmalarni birlashtirib, asosli qaror va harakat rejasini ishlab chiqishda namoyon bo‘ladi."},
{"m":452,"c":"KS.06","l":"oz-ozini-rivojlantirish-va-kasbiy-osish","k":"bilish","d":2,"s":"Kasbiy kompetentlikning keng tarqalgan tarkibiy turlarini qaysi javob to‘g‘ri ifodalaydi?","o":["Ijtimoiy, maxsus, shaxsiy, texnologik va ekstremal","Nazariy, tasodifiy, mavsumiy, hududiy va vaqtinchalik","Og‘zaki, yozma, grafik, raqamli va statistik","Tashkiliy, moliyaviy, ma’muriy, siyosiy va xo‘jalik"],"a":0,"e":"Pedagogik manbalarda kasbiy kompetentlik ijtimoiy, maxsus, shaxsiy, texnologik va ekstremal vaziyatlarda harakat qilish kompetentligi kabi tarkiblar orqali tavsiflanadi."},
{"m":855,"c":"PM.GEN.06","l":"pedagogik-etika-nutq-texnika-va-takt","k":"qollash","d":1,"s":"O‘qituvchi yangi mavzuni uzluksiz bayon qildi, o‘quvchilar esa asosan tinglovchi bo‘ldi. Nutqning qaysi shakli ustuvor?","o":["Monologik nutq shakli","Dialogik nutq shakli","Polilogik nutq shakli","Bahs-munozara nutqi"],"a":0,"e":"Bir kishi fikrini izchil bayon qilib, qolganlar asosan tinglagan vaziyat monologik nutqqa xos. Dialog va polilogda ikki yoki undan ortiq tomon faol almashinadi."},
{"m":858,"c":"PM.GEN.06","l":"pedagogik-etika-nutq-texnika-va-takt","k":"qollash","d":2,"s":"Ota-ona bahoga e’tiroz bildirdi. O‘qituvchi mezon va o‘quvchi ishlarini ko‘rsatib, bahoning asosini xotirjam tushuntirdi. Qaysi usul qo‘llandi?","o":["Ishontirish usuli","Buyruq berish usuli","Muammodan qochish usuli","Jazolash usuli"],"a":0,"e":"Dalil va mezonlarni ko‘rsatib, suhbatdoshga qarorning asosliligini tushuntirish ishontirish usulidir. Bunda bosim emas, mantiqiy dalil va hurmatli muloqot ustuvor bo‘ladi."},
{"m":860,"c":"PM.GEN.06","l":"pedagogik-etika-nutq-texnika-va-takt","k":"qollash","d":2,"s":"Yosh pedagog xonaga kirib faqat direktorga salom berdi, boshqa ishtirokchilarni e’tiborsiz qoldirdi. Nizoga sabab bo‘lishi mumkin bo‘lgan qaysi omil buzildi?","o":["Xulq-atvor me’yori","Axborotning to‘liqligi","Vazifaning murakkabligi","Resursning yetarliligi"],"a":0,"e":"Xonadagi barcha ishtirokchilarga hurmat bilan salom berish odob va xulq-atvor me’yoridir. Uni buzish boshqalarda mensimaslik hissini uyg‘otib, munosabatni taranglashtirishi mumkin."},
{"m":861,"c":"PM.GEN.06","l":"pedagogik-etika-nutq-texnika-va-takt","k":"bilish","d":2,"s":"Rahbar buyrug‘i, axloq komissiyasi yoki sud qarori bilan nizoni yakunlash qaysi usullar guruhiga kiradi?","o":["Ma’muriy-huquqiy usullar","Pedagogik rag‘bat usullari","Refleksiv tahlil usullari","Didaktik nazorat usullari"],"a":0,"e":"Buyruq, komissiya qarori va sud qarori vakolatli tuzilmaning majburiy yechimiga tayanadi. Shu sabab ular nizoni hal qilishning ma’muriy-huquqiy usullariga kiradi."},
{"m":913,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"bilish","d":2,"s":"Muayyan davr yakunida o‘qituvchi va o‘quvchi faoliyatini umumlashtirib, keyingi ish mazmunini belgilashga xizmat qiladigan jarayon nima?","o":["Natijalarni hisobga olish","Bir martalik tekshirish","Boshlang‘ich tashxislash","Joriy nazorat qilish"],"a":0,"e":"Hisobga olish muayyan davrdagi natijalarni jamlaydi va umumlashtiradi. Bu xulosa o‘qituvchi hamda o‘quvchining keyingi faoliyati mazmuni va shaklini belgilashga yordam beradi."},
{"m":1251,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":2,"s":"Dars kuzatuvida o‘qituvchining odobi, nutqi, o‘quvchilar bilan munosabati va tarbiyaviy ta’siri baholandi. Bu qaysi tahlil turi?","o":["Pedagogik tahlil","Didaktik tahlil","Metodologik tahlil","Psixologik tahlil"],"a":0,"e":"Pedagogik tahlil o‘qituvchining madaniyati, odobi, nutqi, o‘quvchilar bilan aloqa o‘rnatishi va darsdagi tarbiyaviy ta’sirini yaxlit baholaydi."},
{"m":1252,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":2,"s":"Darsdagi mazmunning ilmiyligi, izchilligi, ko‘rgazmaliligi va oddiydan murakkabga berilishi qaysi tahlilda tekshiriladi?","o":["Didaktik tahlilda","Pedagogik tahlilda","Metodologik tahlilda","Psixologik tahlilda"],"a":0,"e":"Didaktik tahlil ta’lim mazmuni va jarayonining ilmiyligi, izchilligi, tushunarliligi, ko‘rgazmaliligi hamda bilimning hayot bilan bog‘lanishini baholaydi."},
{"m":1253,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":2,"s":"Darsda davlat talablari, milliy qadriyatlar va fan rivojiga hissa qo‘shgan olimlar merosidan foydalanish qaysi tahlil doirasida baholanadi?","o":["Metodologik tahlil","Didaktik tahlil","Psixologik tahlil","Uslubiy tahlil"],"a":0,"e":"Metodologik tahlil mavzuning davlat talablari, milliy va umuminsoniy qadriyatlar, ilmiy dunyoqarash hamda soha rivoji bilan asosli bog‘lanishini ko‘rib chiqadi."},
{"m":1254,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":2,"s":"Mavzuni ajratilgan vaqtda, o‘quvchi xususiyatlariga mos metodlar bilan yetkazish va izlanishga undash qaysi tahlilning obyekti?","o":["Uslubiy tahlilning","Didaktik tahlilning","Metodologik tahlilning","Psixologik tahlilning"],"a":0,"e":"Uslubiy tahlil o‘qituvchining mavzuga mos usul va vositalarni tanlashi, vaqtni boshqarishi hamda o‘quvchini mustaqil fikrlash va izlanishga jalb etishini baholaydi."},
{"m":1255,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":2,"s":"O‘quvchilarning kayfiyati, diqqati, xotirasi, tafakkuri, qiziqishi va irodasi dars tahlilining qaysi turida o‘rganiladi?","o":["Psixologik tahlilda","Didaktik tahlilda","Metodologik tahlilda","Uslubiy tahlilda"],"a":0,"e":"Psixologik tahlil dars ishtirokchilarining ruhiy holati, diqqat, xotira, tafakkur, qiziqish, motivatsiya va irodaviy xususiyatlarini hisobga oladi."},
{"m":1256,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"qollash","d":2,"s":"Kuzatuvchi darsda o‘quvchilarning kayfiyati, qiziqishi va mashg‘ulotga ruhiy tayyorligini qayd etdi. U qaysi tahlildan foydalandi?","o":["Psixologik tahlildan","Didaktik tahlildan","Metodologik tahlildan","Uslubiy tahlildan"],"a":0,"e":"Kayfiyat, qiziqish va ruhiy tayyorgarlik o‘quvchining psixologik holatini ifodalaydi. Shuning uchun kuzatuv psixologik dars tahliliga kiradi."},
{"m":1257,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"qollash","d":2,"s":"Kuzatuvchi tarbiya darsida milliy qadriyatlar va allomalar merosidan o‘rinli foydalanilganini qayd etdi. Qaysi tahlil turi qo‘llandi?","o":["Metodologik tahlil","Didaktik tahlil","Psixologik tahlil","Uslubiy tahlil"],"a":0,"e":"Milliy qadriyatlar, ilmiy meros va dunyoqarash asoslarining dars mazmuniga singdirilishini baholash metodologik tahlil vazifasidir."},
{"m":1258,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"qollash","d":2,"s":"Kuzatuvchi mavzu ilmiy, hayotiy va oddiydan murakkabga izchil tushuntirilganini qayd etdi. Qaysi dars tahlili qo‘llandi?","o":["Didaktik tahlil","Pedagogik tahlil","Psixologik tahlil","Uslubiy tahlil"],"a":0,"e":"Mazmunning ilmiyligi, hayot bilan bog‘liqligi va oddiydan murakkabga izchil tashkil etilishi didaktik tahlil mezonlaridir."},
{"m":1333,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":2,"s":"Ta’lim jarayonini bevosita va tizimli kuzatib, hodisalarni tabiiy sharoitda qayd etishga asoslangan tadqiqot metodi qaysi?","o":["Pedagogik kuzatish metodi","Pedagogik tajriba metodi","So‘rovnoma o‘tkazish metodi","Matematik tahlil metodi"],"a":0,"e":"Pedagogik kuzatish jarayonga aralashmasdan yoki oldindan belgilangan mezonlar asosida ta’lim hodisalarini tabiiy sharoitda maqsadli va tizimli qayd etadi."},
{"m":1336,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":2,"s":"Ta’lim muassasasidagi reja, jurnal, bayonnoma va hisobotlarni o‘rganib faoliyat natijalarini aniqlash qaysi tadqiqot metodi?","o":["Hujjatlarni tahlil qilish","Pedagogik kuzatish o‘tkazish","Og‘zaki suhbat tashkil etish","Nazorat tajribasi o‘tkazish"],"a":0,"e":"Reja, jurnal, bayonnoma va hisobot kabi rasmiy manbalardagi ma’lumotlarni maqsadli o‘rganish ta’lim muassasasi hujjatlarini tahlil qilish metodidir."},
{"m":1390,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":2,"s":"Ta’lim paradigmasi tushunchasini qaysi ta’rif to‘g‘ri ifodalaydi?","o":["Ta’lim maqsadi va jarayoniga doir konseptual qarashlar tizimi","Darsda ishlatiladigan metod va vositalarning oddiy ro‘yxati","Maktabdagi kundalik tashkiliy ishlar va navbatchilik jadvali","O‘quvchining chorak baholari yozilgan yakuniy hisoboti"],"a":0,"e":"Ta’lim paradigmasi ta’limning maqsadi, inson va bilim haqidagi tasavvur, o‘qituvchi-o‘quvchi roli hamda jarayonni tashkil etishga oid asosiy konseptual qarashlar tizimidir."},
{"m":1396,"c":"PM.GEN.02","l":"pedagogikaning-asosiy-tamoyillari","k":"bilish","d":1,"s":"Didaktik manbalarda ta’lim qonuniyatlari qamroviga ko‘ra qanday ikki guruhga ajratiladi?","o":["Umumiy va xususiy qonuniyatlar","Nazariy va tasodifiy qonuniyatlar","Ichki va ma’muriy qonuniyatlar","Doimiy va mavsumiy qonuniyatlar"],"a":0,"e":"Ta’lim jarayonining butun tizimiga taalluqli bog‘lanishlar umumiy, uning ayrim tarkibiy qismlarida namoyon bo‘ladigan bog‘lanishlar esa xususiy qonuniyatlar deb qaraladi."},
{"m":1435,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":1,"s":"Ta’lim natijasining an’anaviy uchligi qaysi tushunchalardan iborat?","o":["Bilim, ko‘nikma va malaka","Maqsad, metod va vosita","Dars, nazorat va baho","Ta’lim, tarbiya va rivojlanish"],"a":0,"e":"An’anaviy yondashuvda ta’lim natijalari bilim, ko‘nikma va malaka uchligi bilan ifodalanadi. Kompetensiyaviy yondashuv bu natijalarni amaliy faoliyat bilan kengaytiradi."},
{"m":1478,"c":"PM.GEN.08","l":"talim-texnologiyalari-va-vaziyatga-mos-tanlov","k":"bilish","d":2,"s":"Alohida dars elementi, ko‘nikma yoki shaxsiy sifatni shakllantirishga qaratilgan pedagogik texnologiya qaysi darajaga kiradi?","o":["Lokal mikro darajaga","Umumpedagogik makro darajaga","Xususiy-metodik mezo darajaga","Tizimlararo global darajaga"],"a":0,"e":"Lokal yoki mikrotexnologiya o‘quv-tarbiya jarayonining alohida qismi, muayyan ko‘nikma, amal yoki sifatni shakllantirishga xizmat qiladi."},
{"m":1479,"c":"PM.GEN.08","l":"talim-texnologiyalari-va-vaziyatga-mos-tanlov","k":"bilish","d":2,"s":"Muayyan o‘quv fanini o‘qitish jarayonini yaxlit loyihalashga qaratilgan texnologiya qaysi darajaga tegishli?","o":["Xususiy-metodik mezo darajaga","Umumpedagogik makro darajaga","Lokal mikro darajaga","Tizimlararo global darajaga"],"a":0,"e":"Xususiy-metodik yoki mezo darajadagi texnologiya muayyan fan, kurs yoxud ta’lim yo‘nalishini o‘qitish jarayonini loyihalash va amalga oshirishni qamrab oladi."},
{"m":1882,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"qollash","d":2,"s":"O‘quvchi o‘rgangan qoida va formulani yangi vaziyatdagi masalani yechishda to‘g‘ri ishlatdi. Bu Bloom taksonomiyasining qaysi darajasi?","o":["Qo‘llash darajasi","Eslab qolish darajasi","Tushunish darajasi","Tahlil qilish darajasi"],"a":0,"e":"O‘zlashtirilgan qoida, model yoki formuladan tanish bo‘lmagan vazifani bajarishda foydalanish Bloom taksonomiyasidagi qo‘llash darajasini ko‘rsatadi."},
{"m":1886,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"qollash","d":2,"s":"O‘quvchi xulosani oldindan belgilangan mezonlar asosida tekshirib, dalilga mosligi haqida hukm chiqardi. Bu Bloomning qaysi darajasi?","o":["Baholash darajasi","Yaratish darajasi","Qo‘llash darajasi","Tahlil qilish darajasi"],"a":0,"e":"Mezon asosida fikr, mahsulot yoki xulosaning sifatini aniqlash va dalillangan hukm chiqarish Bloom taksonomiyasidagi baholash darajasiga kiradi."},
{"m":1889,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"qollash","d":2,"s":"O‘quvchi hayvonlarni berilgan belgilariga ko‘ra uy va yovvoyi guruhlarga ajratdi. Bu Bloomning qaysi kognitiv jarayoniga misol?","o":["Tushunishdagi tasniflashga","Baholashdagi hukm chiqarishga","Yaratishdagi loyihalashga","Qo‘llashdagi bajarishga"],"a":0,"e":"Obyektlarni muhim belgilariga ko‘ra toifalarga ajratish yangilangan Bloom taksonomiyasida tushunish darajasidagi tasniflash kognitiv jarayoniga kiradi."},
{"m":2190,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"qollash","d":2,"s":"O‘quvchi bir necha fan bilimlarini birlashtirib, yangi tajriba rejasini ishlab chiqdi. Bu yangilangan Bloom taksonomiyasining qaysi darajasi?","o":["Yaratish darajasi","Tahlil qilish darajasi","Qo‘llash darajasi","Tushunish darajasi"],"a":0,"e":"Bir necha manbadagi bilimlarni yangi tuzilma, reja yoki mahsulotga birlashtirish yangilangan Bloom taksonomiyasining eng yuqori — yaratish darajasiga kiradi."},
{"m":3101,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":1,"s":"“Didaktika” atamasining kelib chiqishi va mazmuni qaysi javobda to‘g‘ri berilgan?","o":["Yunoncha didaktikos — o‘rgatuvchi, ta’lim nazariyasi","Lotincha educatio — tarbiya, axloq nazariyasi","Inglizcha teaching — nazorat, baholash nazariyasi","Fransuzcha méthode — usul, boshqaruv nazariyasi"],"a":0,"e":"Didaktika atamasi yunoncha didaktikos — o‘rgatuvchi va didasko — o‘rganaman so‘zlari bilan bog‘liq bo‘lib, pedagogikaning ta’lim nazariyasini o‘rganuvchi bo‘limidir."},
{"m":3102,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":1,"s":"Didaktika asosan qaysi masalalarni tadqiq etadi?","o":["Ta’lim maqsadi, mazmuni, qonuniyatlari, metodlari va natijalarini","Maktab binosi va jihozlaridan foydalanish tartibini","O‘qituvchining mehnat huquqi va ish vaqti hisobini","Ta’lim muassasasining moliyaviy va xo‘jalik faoliyatini"],"a":0,"e":"Didaktika ta’lim jarayonining maqsadi, mazmuni, qonuniyat va tamoyillari, o‘qituvchi-o‘quvchi faoliyati, shakl, metod, vosita hamda natijalarini tadqiq etadi."},
{"m":3112,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":2,"s":"Pedagogika fanining prognostik vazifasi nimani anglatadi?","o":["Ta’lim rivojini ilmiy bashoratlash va strategiyalar belgilashni","Mavjud tajribani faqat tasvirlab qayd etishni","O‘quvchi davomatini kundalik hisoblab borishni","Darslik matnini grammatik jihatdan tahrirlashni"],"a":0,"e":"Prognostik vazifa ilmiy dalillarga tayangan holda ta’lim-tarbiya tizimining istiqbolini bashoratlash, maqsad va rivojlanish strategiyalarini belgilashni anglatadi."},
{"m":3222,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":1,"s":"Quyidagilardan qaysi biri didaktikaning asosiy kategoriyalariga kiradi?","o":["Ta’lim, o‘qitish, bilim, ko‘nikma, metod va natija","Bino, inventar, smeta, ta’mir, transport va hisobot","Huquq, jazo, buyruq, vakolat, intizom va nazorat","Bozor, narx, foyda, xarajat, kredit va investitsiya"],"a":0,"e":"Didaktikaning asosiy kategoriyalari ta’lim va o‘qitish, bilim, ko‘nikma, malaka, kompetensiya, maqsad, mazmun, shakl, metod, vosita va natijani qamrab oladi."}
] $bank$::jsonb) source(v);
DO $task530_b11$
DECLARE b task530_batch11%rowtype;actor uuid;subject_id uuid;construct_id uuid;lesson_id uuid;question_id uuid;option_id uuid;option_ids uuid[];i int;n int;bad int;bad_id uuid;bad_code text;bad_source text;
BEGIN
IF (SELECT count(*) FROM task530_batch11)<>30 THEN RAISE EXCEPTION 'TASK530_B11_COUNT';END IF;
IF EXISTS(SELECT 1 FROM task530_batch11 t JOIN public.questions q ON q.source_reference='telegram:@PedMahoratGuli:'||t.message_id OR q.source_reference LIKE 'telegram:@PedMahoratGuli:'||t.message_id||'|%') THEN RAISE EXCEPTION 'TASK530_B11_SOURCE_ALREADY_REPRESENTED';END IF;
SELECT id INTO STRICT actor FROM public.profiles WHERE role='admin' AND NOT coalesce(is_blocked,false);IF (SELECT count(*) FROM public.profiles WHERE role='admin' AND NOT coalesce(is_blocked,false))<>1 THEN RAISE EXCEPTION 'TASK530_B11_OWNER_NOT_UNIQUE';END IF;SELECT id INTO STRICT subject_id FROM public.subjects WHERE code='informatika';CREATE TEMP TABLE task530_b11_ids(id uuid PRIMARY KEY) ON COMMIT DROP;
FOR b IN SELECT * FROM task530_batch11 ORDER BY message_id LOOP SELECT c.id,l.id INTO STRICT construct_id,lesson_id FROM public.constructs c JOIN public.lesson_constructs lc ON lc.construct_id=c.id JOIN public.lessons l ON l.id=lc.lesson_id WHERE c.code=b.construct_code AND c.is_active AND l.slug=b.lesson_slug AND l.status='published';IF EXISTS(SELECT 1 FROM public.questions q WHERE q.status IN('review','published') AND regexp_replace(lower(btrim(q.stem_md)),'[^[:alnum:]]+','','g')=regexp_replace(lower(btrim(b.stem_md)),'[^[:alnum:]]+','','g')) THEN RAISE EXCEPTION 'TASK530_B11_ACTIVE_EXACT_DUPLICATE_%',b.message_id;END IF;question_id:=gen_random_uuid();INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,status,author_id,is_generated,source_lesson_id,source_reference) VALUES(question_id,subject_id,construct_id,CASE WHEN b.construct_code LIKE 'KS.%' THEN 'KS' ELSE 'PM.GEN' END,'Y1',b.cognitive,b.difficulty,b.stem_md,'review',NULL,true,lesson_id,b.source_reference);INSERT INTO task530_b11_ids VALUES(question_id);option_ids:=ARRAY[]::uuid[];FOR i IN 0..3 LOOP option_id:=gen_random_uuid();option_ids:=array_append(option_ids,option_id);INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(option_id,question_id,'a',i,b.options->>i);END LOOP;INSERT INTO public.question_keys(question_id,payload,explanation_md) VALUES(question_id,jsonb_build_object('correct_option_id',option_ids[b.correct_index+1]),b.explanation_md);END LOOP;
WITH x AS(SELECT q.id,count(o.id) oc,count(DISTINCT lower(btrim(o.content_md))) dc,count(*)FILTER(WHERE o.id::text=k.payload->>'correct_option_id') kc,min(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1)) mi,max(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1)) ma,max(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1))FILTER(WHERE o.id::text=k.payload->>'correct_option_id') cw,max(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1))FILTER(WHERE o.id::text<>k.payload->>'correct_option_id') mw FROM task530_b11_ids r JOIN public.questions q ON q.id=r.id JOIN public.question_options o ON o.question_id=q.id AND btrim(o.side)='a' JOIN public.question_keys k ON k.question_id=q.id GROUP BY q.id)SELECT count(*)FILTER(WHERE oc<>4 OR dc<>4 OR kc<>1 OR mi<1 OR ma>mi*1.8 OR cw>mw*1.25),count(*)INTO bad,n FROM x;IF bad<>0 OR n<>30 THEN RAISE EXCEPTION 'TASK530_B11_BALANCE_%_COUNT_%',bad,n;END IF;
INSERT INTO public.pedagogy_owner_release_waivers(question_id,authorized_by,content_fingerprint,authority,provenance)SELECT q.id,actor,public.professional_question_fingerprint(q.id),'owner_explicit_no_external_expert_20261018','TASK-530 batch 11; owner-delegated AI expert rewrite of PedMahoratGuli items; key independently checked; independent human expert signoff NOT claimed' FROM task530_b11_ids r JOIN public.questions q ON q.id=r.id;GET DIAGNOSTICS n=ROW_COUNT;IF n<>30 THEN RAISE EXCEPTION 'TASK530_B11_WAIVERS_%',n;END IF;
SELECT r.id,q.source_reference,s.finding_code INTO bad_id,bad_source,bad_code FROM task530_b11_ids r JOIN public.questions q ON q.id=r.id CROSS JOIN LATERAL public.pedagogy_semantic_quality_signals(r.id)s WHERE s.severity='high' ORDER BY r.id,s.finding_code LIMIT 1;IF bad_id IS NOT NULL THEN RAISE EXCEPTION 'TASK530_B11_SEMANTIC_%_%',bad_source,bad_code;END IF;
UPDATE public.questions q SET status='published',updated_at=now() FROM task530_b11_ids r WHERE q.id=r.id AND q.status='review';GET DIAGNOSTICS n=ROW_COUNT;IF n<>30 THEN RAISE EXCEPTION 'TASK530_B11_PUBLISHED_%',n;END IF;SELECT count(*) INTO n FROM task530_b11_ids r JOIN public.questions q ON q.id=r.id JOIN public.pedagogy_owner_release_waivers w ON w.question_id=q.id JOIN public.pedagogy_published_revisions p ON p.question_id=q.id WHERE q.status='published' AND w.content_fingerprint=public.professional_question_fingerprint(q.id);IF n<>30 THEN RAISE EXCEPTION 'TASK530_B11_POSTFLIGHT_%_OF_30',n;END IF;
END $task530_b11$;COMMIT;
